# Consent is evidence of what a guardian agreed to and when: rows are never edited.
# Withdrawal is a new row. DELETE stays possible so erasing a child's data can remove them.
def _consent_append_only() -> None:
    dialect = op.get_bind().dialect.name
    if dialect == "sqlite":
        op.execute(
            "CREATE TRIGGER consent_record_no_update BEFORE UPDATE ON consent_record "
            "BEGIN SELECT RAISE(ABORT, 'consent_record is append-only'); END"
        )
    elif dialect == "postgresql":
        op.execute(
            "CREATE FUNCTION consent_record_no_update() RETURNS trigger AS $$ "
            "BEGIN RAISE EXCEPTION 'consent_record is append-only'; END; $$ LANGUAGE plpgsql"
        )
        op.execute(
            "CREATE TRIGGER consent_record_no_update BEFORE UPDATE ON consent_record "
            "FOR EACH ROW EXECUTE FUNCTION consent_record_no_update()"
        )
    else:
        raise RuntimeError(f"no append-only trigger for dialect {dialect}")


